-- QUERY A — readiness. Every row with an expected value must show ok = true; last row SUMMARY must say "0 failed".
with checks(check_name, expected, actual) as (
  select 'info: server version', null, (current_setting('server_version'))::text
  union all select 'info: database', null, (current_database())::text
  union all select 'not yet applied: table purchase_correction_requests absent', 'true', (to_regclass('public.purchase_correction_requests') is null)::text
  union all select 'not yet applied: function absent public.purchase_module_access()', 'true', (to_regprocedure('public.purchase_module_access()') is null)::text
  union all select 'not yet applied: function absent public.purchase_correction_request_visible(uuid,uuid)', 'true', (to_regprocedure('public.purchase_correction_request_visible(uuid,uuid)') is null)::text
  union all select 'not yet applied: function absent public.create_purchase_correction_request(text,uuid,text,text)', 'true', (to_regprocedure('public.create_purchase_correction_request(text,uuid,text,text)') is null)::text
  union all select 'not yet applied: function absent public.process_purchase_correction_request(uuid,text)', 'true', (to_regprocedure('public.process_purchase_correction_request(uuid,text)') is null)::text
  union all select 'name free: index purchase_correction_requests_queue', 'true', (to_regclass('public.purchase_correction_requests_queue') is null)::text
  union all select 'name free: index purchase_correction_requests_po', 'true', (to_regclass('public.purchase_correction_requests_po') is null)::text
  union all select 'name free: index purchase_correction_requests_invoice', 'true', (to_regclass('public.purchase_correction_requests_invoice') is null)::text
  union all select 'not yet applied: activity_log_sources row', '0', ((select count(*) from public.activity_log_sources where entity = 'purchase_correction_requests'))::text
  union all select 'dependency: table public.purchase_orders', 'true', (to_regclass('public.purchase_orders') is not null)::text
  union all select 'dependency: table public.purchase_invoices', 'true', (to_regclass('public.purchase_invoices') is not null)::text
  union all select 'dependency: table public.branches', 'true', (to_regclass('public.branches') is not null)::text
  union all select 'dependency: table public.profiles', 'true', (to_regclass('public.profiles') is not null)::text
  union all select 'dependency: table public.role_modules', 'true', (to_regclass('public.role_modules') is not null)::text
  union all select 'dependency: table public.user_branches', 'true', (to_regclass('public.user_branches') is not null)::text
  union all select 'dependency: table public.activity_log_sources', 'true', (to_regclass('public.activity_log_sources') is not null)::text
  union all select 'dependency: table public.activity_log', 'true', (to_regclass('public.activity_log') is not null)::text
  union all select 'dependency: columns purchase_orders', '3', ((select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'purchase_orders' and column_name in ('id', 'no_po', 'branch_id')))::text
  union all select 'dependency: columns purchase_invoices', '4', ((select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'purchase_invoices' and column_name in ('id', 'no_faktur', 'po_id', 'branch_id')))::text
  union all select 'dependency: columns profiles', '3', ((select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name in ('id', 'role', 'is_active')))::text
  union all select 'dependency: columns role_modules', '2', ((select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'role_modules' and column_name in ('role', 'module_id')))::text
  union all select 'dependency: columns activity_log_sources', '10', ((select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'activity_log_sources' and column_name in ('entity', 'module_id', 'label_key', 'value_keys', 'scope_kind', 'identity_keys', 'branch_columns', 'scope_parents', 'metadata_only', 'reader_roles')))::text
  union all select 'dependency: function public.user_can_access_branch(uuid)', 'true', (to_regprocedure('public.user_can_access_branch(uuid)') is not null)::text
  union all select 'dependency: function public.capture_activity_log()', 'true', (to_regprocedure('public.capture_activity_log()') is not null)::text
  union all select 'dependency: function gen_random_uuid()', 'true', (to_regprocedure('gen_random_uuid()') is not null)::text
  union all select 'dependency: roles anon/authenticated/service_role', '3', ((select count(*) from pg_roles where rolname in ('anon', 'authenticated', 'service_role')))::text
  union all select 'dependency: user_role has OWNER/ADMIN/DOCTOR', '3', ((select count(*) from pg_enum where enumtypid = to_regtype('public.user_role') and enumlabel in ('OWNER', 'ADMIN', 'DOCTOR')))::text
)
select check_name, expected, actual,
  case when expected is null then null else actual is not distinct from expected end as ok
from checks
union all
select 'SUMMARY', '0 failed',
  count(*) filter (where expected is not null and actual is distinct from expected) || ' failed',
  count(*) filter (where expected is not null and actual is distinct from expected) = 0
from checks;

